actions.script:
const plan = ec.service.sync().name('mantle.work.ResourceServices.get#TeamPlan').parameters({fromDate: fromDate || null, weeks: weeks,
    rootWorkEffortId: rootWorkEffortId || null, roleTypeId: roleTypeId || null, skillTypeEnumId: skillTypeEnumId || null,
    teamPartyId: teamPartyId || null}).call()?.plan || {}
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const managed = new Set(Array.from(vis.managedProjectIds || []))
const all = !!vis.allProjects
const approver = !!plan.isApprover
const canChange = (alloc) => !alloc.hidden && (approver || (alloc.statusId === 'WealRequested' && alloc.requestedByUserId === ec.user.userId
        && (all || managed.has(alloc.rootWorkEffortId))))
for (const person of Array.from(plan.personList || [])) {
    person.url = '/qapps/Projects/Resources/PersonDetail?partyId=' + encodeURIComponent(person.partyId)
    for (const alloc of Array.from(person.allocationList || [])) alloc.canChange = canChange(alloc)
}
for (const alloc of Array.from(plan.placeholderList || [])) alloc.canChange = canChange(alloc)
const options = plan.options || {}
options.requestProjectOptions = Array.from(options.projectOptions || []).filter((option) => approver || all || managed.has(option.value))
plan.options = options
plan.canRequest = options.requestProjectOptions.length > 0
plan.roleOptions = ec.service.sync().name('ironstone.projects.ResourceServices.get#AllocationRoleOptions').call()?.roleOptions || []
planner = plan

            const dayOf = (value) => { if (value == null || value === '') return ''; const text = String(value); return /^-?\d+$/.test(text) ? new Date(Number(text)).toISOString().slice(0, 10) : text.slice(0, 10) }
edit = null
            const isApprover = !!ec.user.userId && (ec.user.isInGroup('ADMIN') || ec.user.hasPermission('ALLOCATION_APPROVE'))
            const options = ec.service.sync().name('ironstone.projects.ResourceServices.get#AllocationRoleOptions').call() || {}
            let values = {workEffortAllocationId: '', allocWorkEffortId: workEffortId || '', partyId: partyId || '', allocRoleTypeId: '', allocSkillTypeEnumId: '',
                allocFromDate: '', allocThruDate: '', amount: '8', unit: 'h', comments: '', request: 'N'}
            let title = ec.l10n.localize('New allocation')
            if (workEffortAllocationId) {
                const access = ec.service.sync().name('mantle.work.ResourceServices.get#AllocationAccess').parameters({workEffortAllocationId: workEffortAllocationId}).call() || {}
                if (!access.canChange) return
                const row = access.allocation
                values = {workEffortAllocationId: row.workEffortAllocationId, allocWorkEffortId: row.rootWorkEffortId, partyId: row.partyId || '',
                    allocRoleTypeId: row.roleTypeId || '', allocSkillTypeEnumId: row.skillTypeEnumId || '', allocFromDate: dayOf(row.fromDate),
                    allocThruDate: dayOf(row.thruDate), amount: String(row.allocationPercent != null ? row.allocationPercent : (row.hoursPerWeek ?? '')),
                    unit: row.allocationPercent != null ? 'pct' : 'h', comments: row.comments || '', request: 'N'}
                title = ec.l10n.localize('Edit allocation')
            } else {
                const today = ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
                const js = new Date(today + 'T12:00:00Z').getUTCDay()
                const monday = new Date(Date.parse(today + 'T12:00:00Z') - ((js + 6) % 7) * 86400000).toISOString().slice(0, 10)
                values.allocFromDate = monday
                values.allocThruDate = new Date(Date.parse(monday + 'T12:00:00Z') + 27 * 86400000).toISOString().slice(0, 10)
            }
            const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
            const all = !!vis.allProjects
            const ids = isApprover ? (all ? null : Array.from(vis.visibleProjectIds || [])) : Array.from(vis.managedProjectIds || [])
            let projectOptions = []
            if (ids == null || ids.length) {
                let find = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetProject').condition('statusId', 'not-in', ['WeClosed', 'WeCancelled'])
                if (ids != null) find = find.condition('workEffortId', 'in', ids)
                projectOptions = Array.from(find.orderBy('workEffortName').limit(500).disableAuthz().list()).filter((row) => row.isTemplate !== 'Y')
                        .map((row) => ({key: row.workEffortId, text: row.workEffortName + ' (' + row.workEffortId + ')'}))
            }
            if (!workEffortAllocationId && !projectOptions.length) return
            edit = {values: values, title: title, isNew: !workEffortAllocationId, isApprover: isApprover, projectOptions: projectOptions,
                roleOptions: Array.from(options.roleOptions || []).map((one) => ({key: one.value, text: one.label})),
                skillOptions: Array.from(options.skillOptions || []).map((one) => ({key: one.value, text: one.label}))}

const L = (text) => ec.l10n.localize(text)
const value = amount == null || String(amount).trim() === '' ? null : Number(String(amount).trim().replace(',', '.'))
if (value == null || Number.isNaN(value)) { ec.message.addError(L('Give the hours a week, or a percent')); return }
const pct = unit === 'pct'
if (workEffortAllocationId) {
    const out = ec.service.sync().name('mantle.work.ResourceServices.update#Allocation').parameters({workEffortAllocationId: workEffortAllocationId,
        fromDate: fromDate || null, thruDate: thruDate || null, hoursPerWeek: pct ? null : value, allocationPercent: pct ? value : null,
        roleTypeId: roleTypeId ?? null, skillTypeEnumId: skillTypeEnumId ?? null, comments: comments ?? null}).call() || {}
    if (ec.message.hasError()) return
    message = out.message
    return
}
if (!workEffortId) { ec.message.addError(L('Pick the project')); return }
const out = ec.service.sync().name('mantle.work.ResourceServices.create#Allocation').parameters({workEffortId: workEffortId, partyId: partyId || null,
    roleTypeId: roleTypeId || null, skillTypeEnumId: skillTypeEnumId || null, fromDate: fromDate || null, thruDate: thruDate || null,
    hoursPerWeek: pct ? null : value, allocationPercent: pct ? value : null, comments: comments || null,
    request: request === 'Y' || request === 'true' || request === true}).call() || {}
if (ec.message.hasError()) return
workEffortAllocationId = out.workEffortAllocationId
message = out.message

            const dayOf = (value) => { if (value == null || value === '') return ''; const text = String(value); return /^-?\d+$/.test(text) ? new Date(Number(text)).toISOString().slice(0, 10) : text.slice(0, 10) }
const access = ec.service.sync().name('mantle.work.ResourceServices.get#AllocationAccess').parameters({workEffortAllocationId: workEffortAllocationId,
                need: 'change'}).call() || {}
            if (ec.message.hasError()) return
            const shift = (text, days) => { const d = new Date(dayOf(text) + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + days); return d.toISOString().slice(0, 10) }
            let from = fromDate || dayOf(access.allocation.fromDate)
            let thru = thruDate || dayOf(access.allocation.thruDate)
            if (shiftDays) { from = shift(access.allocation.fromDate, Number(shiftDays)); thru = shift(access.allocation.thruDate, Number(shiftDays)) }
            const out = ec.service.sync().name('mantle.work.ResourceServices.update#Allocation').parameters({workEffortAllocationId: workEffortAllocationId,
                fromDate: from, thruDate: thru}).call() || {}
            if (!ec.message.hasError()) message = ec.l10n.localize('Allocation moved')

const names = {approve: 'mantle.work.ResourceServices.approve#Allocation', reject: 'mantle.work.ResourceServices.reject#Allocation',
    cancel: 'mantle.work.ResourceServices.cancel#Allocation', staff: 'mantle.work.ResourceServices.staff#Allocation'}
if (!names[action]) { ec.message.addError(ec.resource.expand('Not an allocation action: ${action}', '', {action})); return }
const params = {workEffortAllocationId: workEffortAllocationId}
if (action === 'reject') params.reason = reason || null
if (action === 'staff') params.partyId = partyId || ''
message = ec.service.sync().name(names[action]).parameters(params).call()?.message || null

const L = (text) => ec.l10n.localize(text)
const ids = String(selectedIds || '').split(',').map((id) => id.trim()).filter((id) => id)
doneCount = 0; failedCount = 0
if (!ids.length) { ec.message.addError(L('Select the allocations first')); return }
if (!['approve', 'reject'].includes(action)) { ec.message.addError(ec.resource.expand('Not an allocation action: ${action}', '', {action})); return }
if (action === 'reject' && !String(reason || '').trim()) { ec.message.addError(L('Say why the allocations are rejected')); return }
const failed = []
for (const id of ids) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('ironstone.projects.ResourceServices.decide#Allocation').parameters({workEffortAllocationId: id, action: action, reason: reason || null}).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        doneCount++
    } catch (err) {
        failedCount++
        failed.push(id)
        ec.logger.warn(`Allocations bulk ${action}: ${id} failed: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
message = ec.resource.expand(action === 'approve' ? '${doneCount} approved' : '${doneCount} rejected', '', {doneCount})
        + (failedCount ? ec.resource.expand('; ${failedCount} not changed (${ids})', '', {failedCount, ids: failed.join(', ')}) : '')

isApprover = !!ec.user.userId && (ec.user.isInGroup('ADMIN') || ec.user.hasPermission('ALLOCATION_APPROVE'))
if (!['requested', 'unstaffed', 'mine', 'allocated', 'all'].includes(list)) list = isApprover ? 'requested' : 'mine'
const out = ec.service.sync().name('mantle.work.ResourceServices.find#Allocations').parameters({list: list, rootWorkEffortId: rootWorkEffortId || null,
    partyId: partyId || null, fromDate: fromDate || null, thruDate: thruDate || null}).call() || {}
counts = out.counts || {}
rowList = ec.service.sync().name('ironstone.projects.ResourceServices.decorate#AllocationRows').parameters({rowList: Array.from(out.rowList || [])}).call()?.rowList || []

const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('mantle.work.ResourceServices.get#AllocationAccess').parameters({workEffortAllocationId: workEffortAllocationId,
    need: 'view'}).call() || {}
if (ec.message.hasError()) return
canStaff = !!access.canChange
ratesShown = ec.user.isInGroup('ADMIN') || ec.user.hasPermission('TIME_ENTRY_RATE')
const rows = Array.from(ec.service.sync().name('mantle.work.ResourceServices.find#Allocations').parameters({list: 'all', rootWorkEffortId: access.allocation.rootWorkEffortId,
    withCounts: false}).call()?.rowList || []).filter((row) => row.workEffortAllocationId === workEffortAllocationId)
allocation = ec.service.sync().name('ironstone.projects.ResourceServices.decorate#AllocationRows').parameters({rowList: rows}).call()?.rowList?.[0] || access.allocation
const out = ec.service.sync().name('mantle.work.ResourceServices.find#StaffingCandidates').parameters({workEffortAllocationId: workEffortAllocationId,
    withRates: ratesShown}).call() || {}
const n = (value) => ec.l10n.format(value, '#,##0.#')
candidateList = Array.from(out.candidateList || []).map((one) => Object.assign({}, one, {
    skillText: one.hasSkill ? (one.skillRating ? ec.resource.expand('Has the skill (${rating} of 5)', '', {rating: one.skillRating}) : L('Has the skill')) : '',
    roleText: one.hasRole ? L('Has the role') : '',
    freeText: ec.resource.expand('${free} h free of ${need} h needed', '', {free: n(one.freeHours), need: n(one.needHours)}),
    fitText: one.fits ? L('Fits') : ec.resource.expand('Short in ${weeks} weeks', '', {weeks: one.shortWeeks}), fitColor: one.fits ? 'positive' : 'warning',
    projectsText: Array.from(one.currentProjects || []).join(', ') || L('No current projects'),
    rateText: ratesShown && one.costRate != null ? ec.l10n.format(one.costRate, '#,##0.00') + (one.costCurrencyUomId ? ' ' + one.costCurrencyUomId : '') + ' / h' : '',
    personUrl: '/qapps/Projects/Resources/PersonDetail?partyId=' + encodeURIComponent(one.partyId)}))

optionList = []
const text = String(term || '').trim().toLowerCase()
const people = {}
const users = Array.from(ec.service.sync().name('ironstone.shared.ChatterServices.search#Users').parameters({term: term || '', limit: 20}).call()?.userList || [])
for (const user of users) if (user.partyId) people[user.partyId] = user.label
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const keepers = Array.from(ec.service.sync().name('mantle.work.TimesheetServices.get#TimeKeepers').call()?.partyIdList || [])
    for (const id of keepers) {
        if (people[id]) continue
        const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
        const name = party ? [party.firstName, party.lastName].filter((part) => part).join(' ') || id : id
        if (!text || name.toLowerCase().includes(text)) people[id] = name
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
const free = {}
const value = amount == null || String(amount).trim() === '' ? null : Number(String(amount))
if (fromDate && thruDate && value > 0) {
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('mantle.work.ResourceServices.find#StaffingCandidates').parameters({fromDate: fromDate, thruDate: thruDate,
            hoursPerWeek: unit === 'pct' ? null : value, allocationPercent: unit === 'pct' ? value : null, limit: 200}).call() || {}
        for (const one of Array.from(out.candidateList || [])) free[one.partyId] = one.minFreeWeek
    } catch (err) { ec.logger.warn(`Allocation people: free hours not read: ${err}`) } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
optionList = Object.keys(people).map((id) => ({value: id, label: people[id] + (free[id] != null ? ' · ' + ec.resource.expand('${hours} h free a week', '',
    {hours: ec.l10n.format(Math.max(0, free[id]), '#,##0.#')}) : '')})).sort((a, b) => a.label.localeCompare(b.label)).slice(0, 30)

allocationList = []
const access = ec.service.sync().name('mantle.work.ResourceServices.get#AllocationAccess').parameters({rootWorkEffortId: workEffortId}).call() || {}
canRequest = !!access.canRequest
canApprove = !!access.canApprove
if (!access.canView) return
const today = ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
const rows = Array.from(ec.service.sync().name('mantle.work.ResourceServices.find#Allocations').parameters({list: 'all', rootWorkEffortId: workEffortId,
    fromDate: today, withCounts: false}).call()?.rowList || []).filter((row) => row.statusId === 'WealRequested' || row.statusId === 'WealAllocated')
allocationList = ec.service.sync().name('ironstone.projects.ResourceServices.decorate#AllocationRows').parameters({rowList: rows}).call()?.rowList || []

canView = false; person = null
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one()
    if (!party || party.partyTypeEnumId !== 'PtyPerson') return
    const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
    if (vis.allProjects || partyId === ec.user.userAccount?.partyId) canView = true
    else {
        const visible = Array.from(vis.visibleProjectIds || [])
        if (visible.length) {
            canView = ec.entity.find('mantle.work.effort.WorkEffortParty').condition('partyId', partyId).condition('workEffortId', 'in', visible)
                    .conditionDate('fromDate', 'thruDate', null).count() > 0
                    || ec.entity.find('mantle.work.effort.WorkEffortAllocation').condition('partyId', partyId).condition('rootWorkEffortId', 'in', visible).count() > 0
        }
    }
    if (!canView) return
    const account = ec.entity.find('moqui.security.UserAccount').condition('partyId', partyId).one()
    person = {partyId: partyId, name: [party.firstName, party.lastName].filter((part) => part).join(' ') || partyId, userId: account?.userId || null,
        username: account?.username || null}
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

const L = (text) => ec.l10n.localize(text)
overview = null
const access = ec.service.sync().name('ironstone.projects.ResourceServices.get#PersonAccess').parameters({partyId: partyId}).call() || {}
if (!access.canView) return
overview = {person: access.person, emailText: '', phoneText: '', organizationText: '', positionText: '', managerList: [], skillList: [], hoursText: '',
    sourceText: '', dayList: [], weekList: [], failedParts: []}
const part = (name, run) => {
    ec.message.pushErrors()
    try { run(); if (ec.message.hasError()) throw new Error(ec.message.getErrorsString()) } catch (err) {
        overview.failedParts.push(name)
        ec.logger.error(`Person ${partyId}: ${name} left out: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
const nameOf = (id) => {
    const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
    return party ? (party.organizationName || [party.firstName, party.lastName].filter((one) => one).join(' ') || id) : id
}
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    part('contact', () => {
        for (const row of ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', partyId).conditionDate('fromDate', 'thruDate', null).list()) {
            if (row.contactMechTypeEnumId === 'CmtEmailAddress' && !overview.emailText) overview.emailText = row.infoString || ''
            if (row.contactMechTypeEnumId === 'CmtTelecomNumber' && !overview.phoneText)
                overview.phoneText = [row.countryCode ? '+' + row.countryCode : '', row.areaCode, row.contactNumber].filter((one) => one).join(' ')
        }
        const orgs = Array.from(ec.entity.find('mantle.party.PartyRelationship').condition('fromPartyId', partyId)
                .condition('relationshipTypeEnumId', 'in', ['PrtEmployee', 'PrtMember', 'PrtContractor']).conditionDate('fromDate', 'thruDate', null).list())
                .map((row) => nameOf(row.toPartyId))
        overview.organizationText = Array.from(new Set(orgs)).join(', ')
    })
    part('position', () => {
        const rows = Array.from(ec.entity.find('mantle.humanres.position.EmplPositionParty').condition('partyId', partyId)
                .conditionDate('fromDate', 'thruDate', null).list())
        overview.positionText = rows.map((row) => {
            const position = ec.entity.find('mantle.humanres.position.EmplPosition').condition('emplPositionId', row.emplPositionId).one()
            const cls = position?.emplPositionClassId ? ec.entity.find('mantle.humanres.position.EmplPositionClass').condition('emplPositionClassId', position.emplPositionClassId).one() : null
            return position?.description || cls?.title || row.emplPositionId
        }).join(', ')
        for (const row of ec.entity.find('mantle.party.PartyRelationship').condition('toPartyId', partyId).condition('relationshipTypeEnumId', 'PrtManager')
                .conditionDate('fromDate', 'thruDate', null).list()) overview.managerList.push({partyId: row.fromPartyId, name: nameOf(row.fromPartyId),
                    url: '/qapps/Projects/Resources/PersonDetail?partyId=' + encodeURIComponent(row.fromPartyId)})
    })
    part('skills', () => {
        overview.skillList = Array.from(ec.entity.find('mantle.humanres.ability.PartySkill').condition('partyId', partyId).list()).map((row) => {
            const rating = row.rating != null ? Number(String(row.rating)) : (row.skillLevel != null ? Number(String(row.skillLevel)) : null)
            return {skillTypeEnumId: row.skillTypeEnumId, label: ec.entity.find('moqui.basic.Enumeration').condition('enumId', row.skillTypeEnumId).useCache(true).one()?.description
                || row.skillTypeEnumId, rating: rating, ratingText: rating != null ? rating + ' / 5' : '',
                yearsText: row.yearsExperience != null ? ec.resource.expand('${years} years', '', {years: row.yearsExperience}) : ''}
        }).sort((a, b) => (b.rating || 0) - (a.rating || 0) || a.label.localeCompare(b.label))
    })
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
part('load', () => {
    const plan = ec.service.sync().name('mantle.work.ResourceServices.get#TeamPlan').parameters({partyIdList: [partyId], weeks: weeks, includePlaceholders: false,
        withOptions: false}).call()?.plan || {}
    const person = Array.from(plan.personList || [])[0]
    if (!person) return
    // impl-people P9 (owner contract, design-projects §15): a People working schedule plans the person's days first
    overview.sourceText = person.source === 'schedule' ? L('Their working schedule (People)')
            : person.source === 'available' ? L('Their working hours (calendar settings)') : L('The timesheet policy\'s working week')
    const n = (value) => ec.l10n.format(value, '#,##0.#')
    const fmt = (day) => ec.l10n.format(ec.l10n.parseTimestamp(day + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'), 'MMM d')
    overview.weekList = Array.from(person.weekList || []).map((week) => Object.assign({}, week, {weekText: fmt(week.weekStart),
        capacityText: n(week.capacity) + ' h', allocatedText: n(week.allocated) + ' h' + (week.requested ? ' (+' + n(week.requested) + ' ' + L('requested') + ')' : ''),
        assignedText: n(week.assigned) + ' h', loggedText: week.logged ? n(week.logged) + ' h' : '',
        loadText: week.capacity > 0 ? Math.round(week.load * 100) + ' %' : (week.allocated || week.assigned ? L('No capacity') : ''),
        loadColor: week.load > 1.2 ? 'negative' : (week.over ? 'warning' : (week.load >= 0.8 ? 'positive' : 'grey')),
        offText: [week.holidayHours ? n(week.holidayHours) + ' h ' + L('holiday') : '', week.leaveHours ? n(week.leaveHours) + ' h ' + L('leave') : ''].filter((one) => one).join(', '),
        utilizationText: week.utilization != null ? Math.round(week.utilization * 100) + ' %' : ''}))
    const first = overview.weekList[0]
    overview.hoursText = first ? ec.resource.expand('${base} h a week', '', {base: n(first.base)}) : ''
    overview.undatedHours = person.undatedHours
    overview.overWeeks = overview.weekList.filter((week) => week.over).length
})
